function kb.weatherStrength(fq)
local gq=kb.fx(fq)
local hq=gq.dmg/gq.cd/gq.hp/gq.speed*(1+(gq.range-1)/2)
for iq,jq in pairs(gq.kinds)do
hq=hq*(1+bb.rogueShare(iq)*jq)
end
if gq.ice>0 then
local kq=bb.rogueShare(_xd[1813])
hq=hq*(kq+(1-kq)/(1-gq.ice+gq.ice/fb.modFactor(_xd[1941])))
end
if gq.fly>0 then
hq=hq*(1-gq.fly*0.5)
end
if gq.noCC then
hq=hq*0.95
end
if gq.shroud then
hq=hq*0.9
end
if gq.zap then
hq=hq*0.85
end
return hq/kb.weatherK(fq)
end
