function eb.upgradeGain(qkb,rkb,skb,tkb,ukb,vkb)
local wkb,xkb=rkb[skb],rkb[skb+1]
local ykb=(wkb.cd>0 and wkb.damage/wkb.cd or 0)
local zkb=(xkb.cd>0 and xkb.damage/xkb.cd or 0)*V.aoe(xkb.atk,xkb.range)/math.max(0.3,V.aoe(wkb.atk,wkb.range))
local Akb=ykb>0 and qkb*(zkb/ykb-1)or(vkb or 0)
local Bkb=rkb[skb+2]
if Bkb and skb+1<rkb.max and Bkb.cd>0 and xkb.cd>0 and ykb>0 then
local Ckb=qkb*((Bkb.damage/Bkb.cd)/ykb-1)
local Dkb=tkb+Bkb.cost*ukb
if Ckb/Dkb>Akb/tkb then
Akb=Akb+(Ckb/Dkb*tkb-Akb)*0.5
end
end
local Ekb=(xkb.range or 0)>(wkb.range or 0)and(1+((xkb.range-wkb.range)/math.max(1,wkb.range)))or 1
return math.max(0,Akb)*Ekb
end
function eb.dpsFor(Fkb,Gkb)
if Gkb<=0 then
return 0
end
local Hkb={}
for Ikb,Jkb in ipairs(Fkb)do
if not Jkb.farm and Jkb.gain>0 then
table.insert(Hkb,Jkb)
end
end
table.sort(Hkb,function(Kkb,Lkb)
return Kkb.gain/Kkb.cost>Lkb.gain/Lkb.cost
end)
local Mkb,Nkb=0,0
for Okb,Pkb in ipairs(Hkb)do
if Gkb<=0 then
break
end
Nkb=Pkb.gain/Pkb.cost
local Qkb=math.min(1,Gkb/Pkb.cost)
Mkb=Mkb+Pkb.gain*Qkb
Gkb=Gkb-Pkb.cost*Qkb
end
return Mkb+math.max(0,Gkb)*Nkb*0.7
end
function eb.shieldDps(Rkb,Skb,Tkb,Ukb,Vkb,Wkb,Xkb)
if(Ukb or 0)<=0 or(Rkb or 0)<=0 or(Vkb or 0)<=0 then
return Rkb or 0
end
Skb,Tkb,Wkb=math.max(0.3,Skb or 2),math.max(1,Tkb or 1),Wkb or 1
local Ykb=Rkb*Wkb*Skb/Tkb
return Vkb*Tkb/((Ukb/math.max(1,Xkb or 1)+math.max(1,Vkb/Ykb))*Skb)/Wkb
end
function eb.shieldGain(Zkb,_kb,alb,blb,clb,dlb,elb,flb)
local glb,hlb=V.attackInfo(_kb.atk,_kb.range),V.attackInfo(blb.atk,blb.range)
local ilb=eb.shieldDps(Zkb,(tonumber(_kb.cd)or 2)*(elb or 1),glb.n,clb,dlb,flb,glb.hits)
local jlb=eb.shieldDps(alb,(tonumber(blb.cd)or 2)*(elb or 1),hlb.n,clb,dlb,flb,hlb.hits)
local klb=math.max(0,((tonumber(blb.range)or 0)-(tonumber(_kb.range)or 0))/math.max(1,tonumber(_kb.range)or 1))
return math.max(0,jlb-ilb)+ilb*klb
end
function eb.shieldWork(llb,mlb,nlb,olb,plb,qlb,rlb,slb,tlb)
if(olb or 0)<=0 then
return 0
end
local ulb=3*olb*(plb or 1)/math.max(1,qlb or 20)
if(nlb or 0)>=ulb then
return 0
end
return math.max(1,llb or 1)*math.max(1,tlb or 1)/math.max(0.3,mlb or 2)*math.min(rlb or 0,slb or 0)
end
function eb.holdGain(vlb,wlb,xlb,ylb)
if not vlb or(wlb or 0)<=0 then
return 0
end
local zlb,Alb=tonumber(vlb.stun)or 0,tonumber(vlb.slowTime)or 0
if zlb<=0 and Alb<=0 then
return 0
end
local Blb,Clb=zlb>0 and zlb or Alb,zlb>0 and 1 or(tonumber(vlb.slowPct)or 0.3)
local Dlb=Clb*Blb/(Blb+(tonumber(vlb.ccCd)or 8))
local Elb=Dlb/math.max(0.1,1-Dlb)
return wlb*Elb*U.clamp(xlb or 0.5,0,1)*math.min(1,(tonumber(vlb.n)or 1)/2)/(1+(ylb or 0))
end
function eb.bleedGain(Flb,Glb,Hlb,Ilb)
if(Flb or 0)<=0 then
return 0
end
local Jlb=Glb or 0
for Klb,Llb in ipairs(Hlb or{})do
Jlb=math.max(Jlb,(tonumber(Llb.hp)or 0)*0.5)
end
return Flb*Jlb*(Ilb and 0.5 or 1)
end
function eb.bleedShare(Mlb,Nlb,Olb,Plb)
if Mlb<=0 or not Nlb then
return 0
end
if Plb then
return Nlb==0 and Mlb or Mlb/(Nlb+1)
end
return Olb<Nlb and Mlb/(Nlb-Olb)or 0
end
function eb.keepsUp(Qlb,Rlb,Slb,Tlb,Ulb)
local Vlb=Qlb.coming
if not(Vlb and#Vlb>0 and Qlb.waveSec)then
return true
end
local Wlb=Qlb.eff or 1
local Xlb=Qlb.money-Slb
local Ylb=(Qlb.teamDps or 0)*(Qlb.shieldK or 1)+(Tlb or 0)*Wlb+eb.dpsFor(Rlb,math.max(0,Xlb))*Wlb
local Zlb=(Qlb.farmNow or 0)+(Ulb or 0)
local amb=(Qlb.roadSec or 130)*U.clamp(Qlb.cover or 0.6,0.1,1)
local bmb=Qlb.hpAlive or 0
for cmb,dmb in ipairs(Vlb)do
bmb=math.max(0,bmb+dmb.hp-Ylb*Qlb.waveSec)
local emb=Ylb*amb
if bmb>emb then
return false,cmb,emb/math.max(1,bmb)
end
if cmb< #Vlb then
Ylb=Ylb+eb.dpsFor(Rlb,(dmb.reward or 0)+Zlb)*Wlb*(0.85^cmb)
end
end
return true
end
function eb.decide(fmb,gmb)
local hmb=U.clamp(gmb.cover or 0.6,0.1,1)
local imb=math.max(O.clearSec,0.7*(gmb.roadSec or 50)*hmb)
local jmb=(gmb.clearSec or 0)>imb
gmb.piling=gmb.piling and jmb
local kmb=gmb.attackers>0 and gmb.pressure<math.min(O.safeReach,hmb*0.75)and not gmb.piling and not jmb
local lmb=gmb.pressure>=math.min(O.dangerReach,hmb*0.9)or(gmb.piling and gmb.enemies>=18)
local mmb,nmb
for omb,pmb in ipairs(fmb)do
if pmb.farm then
if O.farmUnits and pmb.gain>0 then
pmb.payback=pmb.cost/pmb.gain
if gmb.left-1>=pmb.payback+(gmb.farmSpare or O.farmSpare)and(not mmb or pmb.payback<mmb.payback)then
mmb=pmb
end
end
else
pmb.ratio=pmb.gain/math.max(1,pmb.cost)
if not nmb or pmb.ratio>nmb.ratio then
nmb=pmb
end
end
end
if gmb.leak and gmb.attackers>0 then
local qmb
for rmb,smb in ipairs(fmb)do
local tmb=not gmb.airLeak or(smb.e and bb.cardAir(smb.e.id))
if smb.place and not smb.farm and tmb and smb.cost<=gmb.money and not(smb.e and V.allyBuff(smb.e.id))and(not qmb or smb.gain>qmb.gain)then
qmb=smb
end
end
if qmb then
return qmb,string.format(_xd[3038],math.floor(gmb.leak*100))
end
end
local umb=gmb.future<gmb.wantLeft*1.1
local vmb,wmb,xmb=true,nil,nil
if mmb then
vmb,wmb,xmb=eb.keepsUp(gmb,fmb,mmb.cost,0,mmb.gain)
end
local ymb=gmb.coming and not eb.keepsUp(gmb,fmb,0,0,0)
local zmb=false
if bb.random and mmb and not lmb and gmb.attackers>=2 and mmb.payback<=gmb.left/3 then
local Amb=0
for Bmb,Cmb in ipairs(bb.mine or{})do
if V.isFarm(Cmb._stats.id.Value)then
Amb=Amb+1
end
end
zmb=not mmb.place or Amb<4
end
if ymb and gmb.attackers>0 then
lmb=true
end
local Dmb=math.max(1,gmb.incomeRate or 20)
local Emb=gmb.waveSec or 20
local function Fmb(Gmb,Hmb,Imb)
local Jmb=math.max(0,(Gmb.cost-gmb.money)/Dmb)
local Kmb=Gmb.gain*math.max(0,Imb-Jmb)
if Hmb then
local Lmb=math.max(0,gmb.money-Gmb.cost)
local Mmb=Jmb+math.max(0,(Hmb.cost-Lmb)/Dmb)
Kmb=Kmb+Hmb.gain*math.max(0,Imb-Mmb)
end
return Kmb
end
local Nmb,Omb
if gmb.attackers==0 and nmb then
local Pmb=4*Emb
local Qmb={}
